<?php
namespace Modules\Ran\Reports;
class SalesReport extends AbstractRanReport{public function title():string{return 'Sales';}public function headings():array{return ['Invoice No','Date','Customer','Status','Subtotal','Making','Tax','Discount','Total','Paid','Balance'];}public function rows(array $f):array{$q=\DB::table('ran_sales as s')->whereNull('s.deleted_at');$this->filter($q,$f,'s.invoice_date','s');return $q->orderByDesc('s.invoice_date')->get(['s.invoice_no','s.invoice_date','s.customer_name','s.status','s.subtotal','s.making_charge_total','s.tax_amount','s.discount_amount','s.total_amount','s.paid_amount','s.balance_amount'])->map(fn($r)=>(array)$r)->all();}public function totals(array $rows):array{return ['Total'=>array_sum(array_column($rows,'total_amount')),'Paid'=>array_sum(array_column($rows,'paid_amount')),'Balance'=>array_sum(array_column($rows,'balance_amount'))];}}
